#include "gmm_save_game.h"
#include "common.h"
#include "zmpclient.h"
#include "zmenu_theme.h"
#include <ctime>
using namespace COMMON;
GMMSaveGame::GMMSaveGame():ZGuiMainMenuBase(){menu_type=GMM_SAVE_GAME;title="Save battle";w=380;h=270;next_refresh_time=0;for(int i=0;i<ZSAVE_USER_SLOTS;++i){slot_button[i].SetType(MMGENERIC_BUTTON);slot_button[i].SetCoords(10,30+i*36);slot_button[i].SetDimensions(208,30);AddWidget(&slot_button[i]);}save_button.SetType(MMGENERIC_BUTTON);save_button.SetCoords(10,234);save_button.SetDimensions(360,24);AddWidget(&save_button);UpdateButtonText();UpdateDimensions();}
void GMMSaveGame::UpdateButtonText(){for(int i=0;i<ZSAVE_USER_SLOTS;++i){ZSaveInfo info;string label=to_string(i+1)+": empty";if(ZSave_ReadInfo(i+1,info)){int secs=std::max(0,(int)info.elapsed);label=to_string(i+1)+": "+info.map_title.substr(0,24)+" / "+to_string(secs/60)+":"+(secs%60<10?"0":"")+to_string(secs%60);}slot_button[i].SetText(label);slot_button[i].SetGreen(i==selected);}ZSaveInfo info;save_button.SetText(string(ZSave_ReadInfo(selected+1,info)?"Overwrite slot ":"Save to slot ")+to_string(selected+1));}
void GMMSaveGame::Process(){if(current_time()>=next_refresh_time){next_refresh_time=current_time()+.5;UpdateButtonText();}}
void GMMSaveGame::HandleWidgetEvent(int event,ZGMMWidget *widget){if(event!=GMM_UNCLICK_EVENT)return;for(int i=0;i<ZSAVE_USER_SLOTS;++i)if(widget==&slot_button[i]){selected=i;UpdateButtonText();return;}if(widget==&save_button){gmm_flags.save_game=true;gmm_flags.save_slot=selected+1;killme=true;}}
bool GMMSaveGame::KeyPress(int key){if(key==SDLK_UP||key==SDLK_DOWN||key==SDLK_TAB){selected=(selected+(key==SDLK_UP?ZSAVE_USER_SLOTS-1:1))%ZSAVE_USER_SLOTS;UpdateButtonText();return true;}if(key==SDLK_RETURN){HandleWidgetEvent(GMM_UNCLICK_EVENT,&save_button);return true;}return ZGuiMainMenuBase::KeyPress(key);}
void GMMSaveGame::RenderContents(ZMap &map,SDL_Surface *dest){ZGuiMainMenuBase::RenderContents(map,dest);ZSaveInfo info;bool occupied=ZSave_ReadInfo(selected+1,info);string path=occupied?info.map_name:"";if(path!=preview_path){preview_path=path;preview.Unload();MapPreview data;if(!path.empty()&&ZMP_ReadMapFilePreview(path,data)&&data.valid){SDL_Surface *image=SDL_CreateSurface(data.preview_width,data.preview_height,SDL_PIXELFORMAT_ARGB8888);if(image){for(int row=0;row<image->h;++row)memcpy((char*)image->pixels+row*image->pitch,data.pixels.data()+row*image->w,image->w*4);preview.LoadBaseImage(image);}}}auto *surface=dest?dest:ZSDL_Surface::GetMainSoftwareSurface();if(preview.GetBaseSurface()&&surface){auto *image=preview.GetBaseSurface();float fit=std::min(140.0f/image->w,105.0f/image->h);SDL_Rect target{x+230+(int)((140-image->w*fit)/2),y+30,(int)(image->w*fit),(int)(image->h*fit)};SDL_BlitSurfaceScaled(image,nullptr,surface,&target,SDL_SCALEMODE_NEAREST);}string context=occupied?(info.campaign_id=="original"?"Original Campaign":info.campaign_id.empty()?"Standalone battle":info.campaign_id):"Empty slot";ZMenuTheme::queueText(context.c_str(),x+230,y+144,11,{244,184,85,255},140);if(occupied){string mission=info.mission_index>=0?"Mission "+to_string(info.mission_index+1):"Custom map";ZMenuTheme::queueText(mission.c_str(),x+230,y+163,11,{218,226,232,255},140);time_t when=info.when;char date[64]={};if(auto *local=localtime(&when))strftime(date,sizeof(date),"%Y-%m-%d %H:%M",local);ZMenuTheme::queueText(date,x+230,y+182,10,{180,193,204,255},140);ZMenuTheme::queueText(bot_difficulty_name[std::max(0,std::min(3,info.difficulty))],x+230,y+200,10,{180,193,204,255},140);}ZMenuTheme::queueText("Select a slot, then Save. Existing slots show Overwrite.",x+10,y+214,10,{180,193,204,255},360);}
